@import "tailwindcss";

/* ==========================================================================
   Instrument Sans
   ========================================================================== */
@font-face {
  font-family: "Instrument Sans";
  src: url("../assets/fonts/InstrumentSans/InstrumentSans-Regular.woff2") format("woff2");
  font-weight: 400;
  font-style: normal;
  font-display: swap;
}
@font-face {
  font-family: "Instrument Sans";
  src: url("../assets/fonts/InstrumentSans/InstrumentSans-Medium.woff2") format("woff2");
  font-weight: 500;
  font-style: normal;
  font-display: swap;
}
@font-face {
  font-family: "Instrument Sans";
  src: url("../assets/fonts/InstrumentSans/InstrumentSans-SemiBold.woff2") format("woff2");
  font-weight: 600;
  font-style: normal;
  font-display: swap;
}
@font-face {
  font-family: "Instrument Sans";
  src: url("../assets/fonts/InstrumentSans/InstrumentSans-Bold.woff2") format("woff2");
  font-weight: 700;
  font-style: normal;
  font-display: swap;
}

/* ==========================================================================
   KarirKit Design Tokens — three layers

   1. Primitive  — raw scales (neutral, brand, status)
   2. Semantic   — purpose aliases (background, fg, border, …)
   3. Component  — control sizing / radius used by @layer components

   Dark mode: light-only for now. Theme switching is deferred; do not add
   ad-hoc dark: utilities until semantic tokens get a .dark override map.
   ========================================================================== */
@theme {
  --font-sans: "Instrument Sans", ui-sans-serif, system-ui, -apple-system, sans-serif;
  --font-display: "Instrument Sans", ui-sans-serif, system-ui, -apple-system, sans-serif;

  /* ---------- Primitive: neutral (owned; was Tailwind slate) ---------- */
  --color-neutral-50: #f8fafc;
  --color-neutral-100: #f1f5f9;
  --color-neutral-200: #e2e8f0;
  --color-neutral-300: #cbd5e1;
  --color-neutral-400: #94a3b8;
  --color-neutral-500: #64748b;
  --color-neutral-600: #475569;
  --color-neutral-700: #334155;
  --color-neutral-800: #1e293b;
  --color-neutral-900: #0f172a;
  --color-neutral-950: #020617;

  /* ---------- Primitive: brand primary ---------- */
  --color-primary-50: #f0f5fe;
  --color-primary-100: #e2ebfd;
  --color-primary-200: #c6d7fb;
  --color-primary-300: #98b6f6;
  --color-primary-400: #5d8bef;
  --color-primary-500: #3d74eb;
  --color-primary-600: #2361e7;
  --color-primary-700: #1950c8;
  --color-primary-800: #1843a0;
  --color-primary-900: #173678;
  --color-primary-950: #112245;

  /* ---------- Primitive: brand secondary ---------- */
  --color-secondary-50: #fff6f0;
  --color-secondary-100: #feeadd;
  --color-secondary-200: #fcd3b6;
  --color-secondary-300: #fab380;
  --color-secondary-400: #f89854;
  --color-secondary-500: #f7893b;
  --color-secondary-600: #f67e28;
  --color-secondary-700: #d56515;
  --color-secondary-800: #ac5415;
  --color-secondary-900: #8c4817;
  --color-secondary-950: #502b11;

  /* Soft mid-stop for brand gradient (was hardcoded #f5f8ff) */
  --color-brand-soft-mid: #f5f8ff;

  /* ---------- Primitive: status (full 50–950) ---------- */
  --color-success-50: #ecfdf5;
  --color-success-100: #d1fae5;
  --color-success-200: #a7f3d0;
  --color-success-300: #6ee7b7;
