  --color-danger-300: #fca5a5;
  --color-danger-400: #f87171;
  --color-danger-500: #ef4444;
  --color-danger-600: #dc2626;
  --color-danger-700: #b91c1c;
  --color-danger-800: #991b1b;
  --color-danger-900: #7f1d1d;
  --color-danger-950: #450a0a;

  --color-info-50: #f0f9ff;
  --color-info-100: #e0f2fe;
  --color-info-200: #bae6fd;
  --color-info-300: #7dd3fc;
  --color-info-400: #38bdf8;
  --color-info-500: #0ea5e9;
  --color-info-600: #0284c7;
  --color-info-700: #0369a1;
  --color-info-800: #075985;
  --color-info-900: #0c4a6e;
  --color-info-950: #082f49;

  /* ---------- Semantic: surfaces & text ---------- */
  --color-background: var(--color-neutral-50);
  --color-surface: #ffffff;
  --color-fg: var(--color-neutral-900);
  --color-fg-muted: var(--color-neutral-500);
  --color-fg-subtle: var(--color-neutral-400);
  --color-border: var(--color-neutral-200);
  --color-border-subtle: var(--color-neutral-100);
  --color-ring: var(--color-primary-500);

  /* ---------- Component / scale tokens ---------- */
  --radius-control: 0.75rem;   /* rounded-control ≈ xl */
  --radius-card: 1rem;         /* rounded-card ≈ 2xl */
  --radius-check: 0.375rem;    /* 6px checkbox */

  --text-btn-lg: 0.9375rem;    /* 15px */
  --text-micro: 0.6875rem;     /* 11px */

  --spacing-check: 1.125rem;   /* 18px */
  --spacing-check-sm: 0.9375rem; /* 15px */

  --z-dropdown: 20;
  --z-sticky: 30;
  --z-overlay: 40;
  --z-toast: 50;

  --ease-out-soft: cubic-bezier(0.16, 1, 0.3, 1);
  --duration-fast: 150ms;
  --duration-normal: 200ms;

  /* Elevation — RGB channels reference owned neutrals / brand */
  --shadow-card: 0 1px 2px 0 color-mix(in srgb, var(--color-neutral-900) 4%, transparent),
    0 12px 24px -10px color-mix(in srgb, var(--color-neutral-900) 10%, transparent);
  --shadow-card-lg: 0 4px 8px 0 color-mix(in srgb, var(--color-neutral-900) 4%, transparent),
    0 24px 48px -12px color-mix(in srgb, var(--color-neutral-900) 18%, transparent);
  --shadow-glow-primary: 0 8px 30px -6px color-mix(in srgb, var(--color-primary-600) 45%, transparent);

  --animate-fade-in: fade-in 0.4s var(--ease-out-soft);
  --animate-spin-slow: spin 0.7s linear infinite;

  @keyframes fade-in {
    from { opacity: 0; transform: translateY(4px); }
    to { opacity: 1; transform: translateY(0); }
  }
}

/* ==========================================================================
   Base — interactive cursor
   ========================================================================== */
@layer base {
  button:not(:disabled),
  [role="button"],
  select,
  summary,
  label:has(input[type="checkbox"]),
  label:has(input[type="radio"]) {
    cursor: pointer;
  }
}

/* ==========================================================================
   Base — smooth scroll (honours reduced motion)
   ========================================================================== */
@layer base {
  html {
    scroll-behavior: smooth;
  }

  @media (prefers-reduced-motion: reduce) {
    html {
      scroll-behavior: auto;
    }

    *,
    *::before,
    *::after {
      animation-duration: 0.01ms !important;
      animation-iteration-count: 1 !important;
      transition-duration: 0.01ms !important;
    }
  }
}

/* ==========================================================================
   Base — scrollbar
   ========================================================================== */
@layer base {
  html {
    scrollbar-width: thin;
    scrollbar-color: var(--color-neutral-200) transparent;
  }

  ::-webkit-scrollbar {
    width: 10px;
    height: 10px;
  }

  ::-webkit-scrollbar-track {
    background: transparent;
  }

  ::-webkit-scrollbar-thumb {
    background-color: var(--color-neutral-100);
    border-radius: 9999px;
    border: 3px solid transparent;
    background-clip: content-box;
  }

  ::-webkit-scrollbar-thumb:hover {
    background-color: var(--color-primary-300);
  }
}

@utility scrollbar-none {
  scrollbar-width: none;
  &::-webkit-scrollbar {
    display: none;
  }
}

/* ==========================================================================
   Brand utilities
   ========================================================================== */
@utility bg-shell {
  background-color: var(--color-background);
  background-image:
    radial-gradient(1200px 600px at 0% -10%, color-mix(in srgb, var(--color-primary-200) 40%, transparent), transparent),
    radial-gradient(1000px 500px at 100% 0%, color-mix(in srgb, var(--color-secondary-200) 35%, transparent), transparent);
  background-attachment: fixed;
}

@utility bg-brand-gradient {
  background-image: linear-gradient(135deg, var(--color-primary-700) 0%, var(--color-primary-600) 55%, var(--color-primary-500) 100%);
}

@utility bg-brand-gradient-soft {
  background-image: linear-gradient(135deg, var(--color-primary-50) 0%, var(--color-brand-soft-mid) 50%, var(--color-secondary-50) 100%);
}

/* ==========================================================================
   Component layer
   ========================================================================== */

