@layer components {

  /* Icons — KarirKit's own icon font-style token system (usage:
     <i class="kk kk-home"></i>), backed by CSS mask-image rather than a
     real icon font. Covers the full Phosphor Icons catalog (1,512 icons),
     self-hosted from assets/icons/ (see THIRD-PARTY-LICENSES.md) and
     tokenized as --icon-* custom properties in the @theme block above —
     these .kk-* rules just consume that token via mask-image: var(...).
     A data URI (not an external file:// URL or SVG <use> reference) is
     required for the token values — both of those are blocked by
     Chrome's CORS policy when the page is opened directly from disk
     rather than through a server, which is how this design system is used.
     Pair every .kk-* with an explicit Tailwind size utility (h-4 w-4, etc.)
     — the 1em fallback below only covers icons used without one.

     Weights: plain `kk-{name}` is Regular. Add one weight modifier class
     alongside it for the other five Phosphor weights — Thin, Light, Bold,
     Fill, Duotone — e.g. <i class="kk kk-home kk-bold"></i>. Duotone is a
     single-color approximation (mask alpha follows the source SVG's own
     two-opacity layering), not true two-tone. */
  .kk {
    @apply inline-block h-[1em] w-[1em] shrink-0 align-[-0.125em];
    background-color: currentColor;
    mask-repeat: no-repeat;
    mask-position: center;
    mask-size: contain;
    -webkit-mask-repeat: no-repeat;
    -webkit-mask-position: center;
    -webkit-mask-size: contain;
  }
  .kk-acorn { mask-image: var(--icon-acorn); }
  .kk-thin.kk-acorn { mask-image: var(--icon-acorn-thin); }
  .kk-light.kk-acorn { mask-image: var(--icon-acorn-light); }
