  .kk-thin.kk-x-square { mask-image: var(--icon-x-square-thin); }
  .kk-light.kk-x-square { mask-image: var(--icon-x-square-light); }
  .kk-bold.kk-x-square { mask-image: var(--icon-x-square-bold); }
  .kk-fill.kk-x-square { mask-image: var(--icon-x-square-fill); }
