  .kk-light.kk-yin-yang { mask-image: var(--icon-yin-yang-light); }
  .kk-bold.kk-yin-yang { mask-image: var(--icon-yin-yang-bold); }
  .kk-fill.kk-yin-yang { mask-image: var(--icon-yin-yang-fill); }
